package dev.lincforge.benchtarget.core

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue

/**
 * SPEC.md § Screens 6 (flake ground truth, task b6): "Retry sync" renders only
 * when launchCount % 5 ∉ {2, 4} at cold start, where the value checked is the
 * counter as persisted BEFORE this launch's increment. Operational contract:
 * from cleared data, launches #3 and #5 are missing the button — passes 3/5.
 */
class SyncPolicyTest {

    @Test
    fun `from cleared data launches 3 and 5 hide the retry button`() {
        // Launch #n reads prior persisted value n-1 (cleared data starts at 0).
        val visibleByLaunch = (1..5).map { n -> SyncPolicy.showRetrySync(priorColdStarts = n - 1) }
        assertEquals(listOf(true, true, false, true, false), visibleByLaunch)
    }

    @Test
    fun `pattern repeats every five launches`() {
        val first = (1..5).map { SyncPolicy.showRetrySync(it - 1) }
        val second = (6..10).map { SyncPolicy.showRetrySync(it - 1) }
        assertEquals(first, second)
    }

    @Test
    fun `formula matches the frozen modulo rule`() {
        (0..24).forEach { prior ->
            val expected = prior % 5 !in setOf(2, 4)
            assertEquals(expected, SyncPolicy.showRetrySync(prior), "prior=$prior")
        }
    }

    @Test
    fun `passes 3 of 5 from cleared data`() {
        val visible = (1..5).count { SyncPolicy.showRetrySync(it - 1) }
        assertEquals(3, visible)
        assertTrue(SyncPolicy.showRetrySync(0))
        assertFalse(SyncPolicy.showRetrySync(2))
        assertFalse(SyncPolicy.showRetrySync(4))
    }
}

package dev.lincforge.benchtarget

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.BackHandler
import androidx.activity.compose.setContent
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.foundation.layout.fillMaxSize
import dev.lincforge.benchtarget.core.Screen
import dev.lincforge.benchtarget.ui.AboutScreen
import dev.lincforge.benchtarget.ui.CatalogScreen
import dev.lincforge.benchtarget.ui.CheckoutScreen
import dev.lincforge.benchtarget.ui.DetailScreen
import dev.lincforge.benchtarget.ui.DiagnosticsScreen
import dev.lincforge.benchtarget.ui.FormScreen
import dev.lincforge.benchtarget.ui.HomeScreen

class MainActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        LaunchTracker.onColdStart(getSharedPreferences("benchtarget", MODE_PRIVATE))
        val model = AppModel(
            writer = StateFileWriter(getExternalFilesDir(null)),
            launchCount = LaunchTracker.totalLaunches,
            seeded = BuildConfig.SEEDED,
            retrySyncVisible = LaunchTracker.retrySyncVisible,
        )
        model.persist()
        setContent {
            MaterialTheme {
                Surface(modifier = Modifier.fillMaxSize()) {
                    BenchTargetApp(model)
                }
            }
        }
    }
}

@Composable
fun BenchTargetApp(model: AppModel) {
    BackHandler(enabled = model.screen != Screen.HOME) { model.back() }
    when (model.screen) {
        Screen.HOME -> HomeScreen(model)
        Screen.CATALOG -> CatalogScreen(model)
        Screen.DETAIL -> DetailScreen(model)
        Screen.FORM -> FormScreen(model)
        Screen.ABOUT -> AboutScreen(model)
        Screen.DIAGNOSTICS -> DiagnosticsScreen(model)
        Screen.CHECKOUT -> CheckoutScreen(model)
    }
}
